def family_init(ctx):
    import math
    bars = ctx.bars
    N = len(bars)
    cl = [float(b["c"]) for b in bars]
    vo = [float(b.get("v") or 0.0) for b in bars]
    mins = [0] * N
    dts = [""] * N
    for j in range(N):
        s = str(bars[j]["t"])
        dts[j] = s[:10]
        try:
            mins[j] = int(s[11:13]) * 60 + int(s[14:16])
        except Exception:
            mins[j] = 0

    days = []
    cur = None
    for j in range(N):
        if dts[j] != cur:
            cur = dts[j]
            days.append([])
        days[-1].append(j)
    nd = len(days)

    # The session close is found from the tape, not from a timezone table: on
    # every session the closing auction bar carries the day's heaviest volume
    # in its back half. Taking the median of the PAST slot_days sessions makes
    # the anchor robust to a single odd print and follows a DST shift on its own.
    cand = [None] * nd
    for k in range(nd):
        idx = days[k]
        half = idx[len(idx) // 2:]
        if not half:
            continue
        best = half[0]
        for j in half:
            if vo[j] > vo[best]:
                best = j
        cand[k] = mins[best]

    look = int(ctx.p.slot_days)
    sess = int(ctx.p.session_min)
    tol = int(ctx.p.tol_min)
    close_i = [None] * nd
    open_i = [None] * nd
    for k in range(nd):
        past = [c for c in cand[max(0, k - look):k] if c is not None]
        if len(past) < 2:
            continue
        past.sort()
        ref = past[len(past) // 2]
        idx = days[k]
        bi = None
        bd = 10 ** 9
        for j in idx:
            d = mins[j] - ref
            if d < 0:
                d = -d
            if d < bd:
                bd = d
                bi = j
        if bi is None or bd > tol:
            continue
        close_i[k] = bi
        om = ref - sess
        bo = None
        bd2 = 10 ** 9
        for j in idx:
            d = mins[j] - om
            if d < 0:
                d = -d
            if d < bd2:
                bd2 = d
                bo = j
        open_i[k] = bo if (bo is not None and bd2 <= tol) else idx[0]

    dr = [None] * nd
    for k in range(1, nd):
        a = close_i[k - 1]
        b = close_i[k]
        if a is None or b is None:
            continue
        if cl[a] > 0.0 and cl[b] > 0.0:
            dr[k] = math.log(cl[b] / cl[a])

    nsig = int(ctx.p.nsig)
    ksig = float(ctx.p.k_sig)
    trig = int(ctx.p.trig_min)
    leg2 = int(ctx.p.leg2)
    sig = [0] * N
    for k in range(1, nd):
        ci = close_i[k]
        pi = close_i[k - 1]
        if ci is None or pi is None:
            continue
        h = [dr[q] for q in range(max(1, k - nsig), k) if dr[q] is not None]
        nh = len(h)
        need = nsig // 2
        if need < 3:
            need = 3
        if nh < need:
            continue
        mu = sum(h) / nh
        var = sum((x - mu) * (x - mu) for x in h) / (nh - 1)
        if var <= 0.0:
            continue
        sd = math.sqrt(var)
        ref = mins[ci] - trig
        ti = None
        bd = 10 ** 9
        for j in days[k]:
            if j >= ci:
                break
            d = mins[j] - ref
            if d < 0:
                d = -d
            if d < bd:
                bd = d
                ti = j
        if ti is None or bd > tol:
            continue
        pc = cl[pi]
        if pc <= 0.0:
            continue
        r = cl[ti] / pc - 1.0
        s = 0
        if r > ksig * sd:
            s = 1
        elif r < -ksig * sd:
            s = -1
        if s == 0:
            continue
        sig[ti] = s
        if leg2 and ci + 1 < N and k + 1 < nd:
            sig[ci + 1] = -s

    # where a position opened on bar j has to be closed: the session close if
    # it opened before it, otherwise the next session's opening bar.
    xat = [-1] * N
    for k in range(nd):
        ci = close_i[k]
        if k + 1 < nd:
            nxt = open_i[k + 1]
            if nxt is None:
                nxt = days[k + 1][-1]
        else:
            nxt = days[k][-1]
        for j in days[k]:
            if ci is not None and j <= ci:
                xat[j] = ci
            else:
                xat[j] = nxt
    ctx.sg = ctx.series(sig, "lev_flow")
    ctx.xat = ctx.series(xat, "exit_at")


def signal(ctx, i):
    s = ctx.sg[i]
    return s if s else 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    e = min(p["entry_i"] for p in ctx.positions)
    x = ctx.xat[e]
    if x is None or x < 0:
        return True
    return i >= x
